// Package app assembles the process-level service dependencies.
package app

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
)

const maxJSONBodyBytes int64 = 1 << 20

var errRequestBodyTooLarge = errors.New("request body too large")

// App is the assembled IAM application. Domain dependencies are added here as
// their packages are introduced by subsequent implementation tasks.
type App struct {
	Config  config.Config
	Clock   domain.Clock
	Users   *repository.UserRepository
	Handler http.Handler
}

// New builds the application from validated configuration.
func New(cfg config.Config) *App {
	return NewWithClock(cfg, domain.RealClock{})
}

// NewWithClock assembles the application with an explicit time dependency.
// Tests and domain services can therefore use a deterministic clock.
func NewWithClock(cfg config.Config, clock domain.Clock) *App {
	if clock == nil {
		clock = domain.RealClock{}
	}
	app := &App{
		Config: cfg,
		Clock:  clock,
		Users:  repository.NewUserRepository(),
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/v1/register", app.handleRegister)
	app.Handler = mux
	return app
}

type registerRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

type dataEnvelope struct {
	Data any `json:"data"`
}

type errorEnvelope struct {
	Error apiError `json:"error"`
}

type apiError struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	RequestID string `json:"request_id"`
}

func (a *App) handleRegister(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeAPIError(w, http.StatusMethodNotAllowed, "invalid", "method not allowed")
		return
	}

	var input registerRequest
	if err := decodeJSONBody(w, r, &input); err != nil {
		if errors.Is(err, errRequestBodyTooLarge) {
			writeAPIError(w, http.StatusRequestEntityTooLarge, string(domain.ErrorInvalid), "request body too large")
			return
		}
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "invalid request body")
		return
	}
	if input.Email == "" || input.Password == "" {
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "email and password are required")
		return
	}

	email, err := domain.ValidateEmail(input.Email)
	if err != nil {
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "invalid email address")
		return
	}
	passwordMaterial, err := domain.HashPassword(input.Password)
	if err != nil {
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "invalid password")
		return
	}
	userID, err := domain.NewUserID()
	if err != nil {
		writeAPIError(w, http.StatusInternalServerError, "internal", "could not create user")
		return
	}
	now := a.Clock.Now()
	user := domain.User{
		ID:               userID,
		Email:            email,
		CreatedAt:        now,
		UpdatedAt:        now,
		PasswordMaterial: passwordMaterial,
	}
	if err := a.Users.Create(user); err != nil {
		if errors.Is(err, domain.ErrConflict) {
			writeAPIError(w, http.StatusConflict, string(domain.ErrorConflict), "email already exists")
			return
		}
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "could not create user")
		return
	}

	writeJSON(w, http.StatusCreated, dataEnvelope{Data: user.PublicProfile()})
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

func writeAPIError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, errorEnvelope{Error: apiError{Code: code, Message: message}})
}

// decodeJSONBody applies the transport-wide JSON request rules: bounded input,
// known fields only, and exactly one JSON value in the body.
func decodeJSONBody(w http.ResponseWriter, r *http.Request, destination any) error {
	r.Body = http.MaxBytesReader(w, r.Body, maxJSONBodyBytes)
	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(destination); err != nil {
		if errors.Is(err, http.ErrBodyReadAfterClose) {
			return errRequestBodyTooLarge
		}
		var maxBytesError *http.MaxBytesError
		if errors.As(err, &maxBytesError) {
			return errRequestBodyTooLarge
		}
		return err
	}
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		if errors.Is(err, http.ErrBodyReadAfterClose) {
			return errRequestBodyTooLarge
		}
		var maxBytesError *http.MaxBytesError
		if errors.As(err, &maxBytesError) {
			return errRequestBodyTooLarge
		}
		return errors.New("request body must contain one JSON value")
	}
	return nil
}
// Package repository contains the in-memory persistence used by the IAM
// application.
package repository

import (
	"sync"

	"benchmark.local/iam/internal/domain"
)

// UserRepository is a concurrency-safe in-memory store for users. The email
// index contains normalized addresses and is maintained under the same lock
// as users, so an email cannot be claimed by two users.
type UserRepository struct {
	mu         sync.RWMutex
	users      map[domain.UserID]domain.User
	emailIndex map[string]domain.UserID
}

// NewUserRepository creates an empty user repository.
func NewUserRepository() *UserRepository {
	return &UserRepository{
		users:      make(map[domain.UserID]domain.User),
		emailIndex: make(map[string]domain.UserID),
	}
}

// Create stores a user and reserves its normalized email address.
func (r *UserRepository) Create(user domain.User) error {
	if r == nil {
		return domain.NewError(domain.ErrorInvalid, "user repository is nil")
	}
	if user.ID == "" {
		return domain.NewError(domain.ErrorInvalid, "user id and email are required")
	}
	key, err := domain.ValidateEmail(user.Email)
	if err != nil {
		return err
	}

	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.users[user.ID]; exists {
		return domain.NewError(domain.ErrorConflict, "user already exists")
	}
	if _, exists := r.emailIndex[key]; exists {
		return domain.NewError(domain.ErrorConflict, "email already exists")
	}
	// Store both the aggregate and its credential byte slices detached from the
	// caller. This keeps later caller mutations from bypassing repository lock.
	user.Email = key
	r.users[user.ID] = cloneUser(user)
	r.emailIndex[key] = user.ID
	return nil
}

// GetByID returns a detached copy of the user with the supplied ID.
func (r *UserRepository) GetByID(id domain.UserID) (domain.User, error) {
	if r == nil {
		return domain.User{}, domain.ErrNotFound
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	user, ok := r.users[id]
	if !ok {
		return domain.User{}, domain.ErrNotFound
	}
	return cloneUser(user), nil
}

// GetByEmail returns a detached copy of the user matching the normalized
// email address. Lookup is case-insensitive and ignores surrounding spaces.
func (r *UserRepository) GetByEmail(email string) (domain.User, error) {
	if r == nil {
		return domain.User{}, domain.ErrNotFound
	}
	key := domain.NormalizeEmail(email)
	r.mu.RLock()
	defer r.mu.RUnlock()
	id, ok := r.emailIndex[key]
	if !ok {
		return domain.User{}, domain.ErrNotFound
	}
	return cloneUser(r.users[id]), nil
}

// Update replaces an existing user and, atomically, updates its email index.
// A changed email must not already belong to another user.
func (r *UserRepository) Update(user domain.User) error {
	if r == nil {
		return domain.NewError(domain.ErrorInvalid, "user repository is nil")
	}
	if user.ID == "" {
		return domain.NewError(domain.ErrorInvalid, "user id and email are required")
	}
	key, err := domain.ValidateEmail(user.Email)
	if err != nil {
		return err
	}

	r.mu.Lock()
	defer r.mu.Unlock()
	previous, exists := r.users[user.ID]
	if !exists {
		return domain.ErrNotFound
	}
	if owner, claimed := r.emailIndex[key]; claimed && owner != user.ID {
		return domain.NewError(domain.ErrorConflict, "email already exists")
	}
	if oldKey := domain.NormalizeEmail(previous.Email); oldKey != key {
		delete(r.emailIndex, oldKey)
	}
	user.Email = key
	r.users[user.ID] = cloneUser(user)
	r.emailIndex[key] = user.ID
	return nil
}

// Delete removes a user and releases its email address.
func (r *UserRepository) Delete(id domain.UserID) error {
	if r == nil {
		return domain.ErrNotFound
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	user, ok := r.users[id]
	if !ok {
		return domain.ErrNotFound
	}
	delete(r.users, id)
	delete(r.emailIndex, domain.NormalizeEmail(user.Email))
	return nil
}

func cloneUser(user domain.User) domain.User {
	user.PasswordMaterial = user.PasswordMaterial.Clone()
	return user
}

package domain

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
	"time"
)

// AccessTokenClaims is the set of claims issued in an access token. Times use
// JWT NumericDate (seconds since the Unix epoch).
type AccessTokenClaims struct {
	Sub   string `json:"sub"`
	Email string `json:"email"`
	Iss   string `json:"iss"`
	Iat   int64  `json:"iat"`
	Exp   int64  `json:"exp"`
	JTI   string `json:"jti"`
}

type accessTokenHeader struct {
	Alg string `json:"alg"`
	Typ string `json:"typ"`
}

// AccessTokenIssuer creates short-lived JWT-compatible HS256 access tokens.
// The clock is injected so token lifetime behavior is deterministic for
// callers that need it to be.
type AccessTokenIssuer struct {
	secret []byte
	issuer string
	ttl    time.Duration
	clock  Clock
}

// AccessTokenValidator validates tokens issued by AccessTokenIssuer. It does
// not trust any identity or authorization data supplied by the caller: all
// claims are taken from the verified token.
type AccessTokenValidator struct {
	secret []byte
	issuer string
	clock  Clock
}

// NewAccessTokenValidator constructs a validator with the supplied signing
// key and expected issuer. The key is copied for the same reason as in the
// issuer: callers cannot mutate validator state after construction.
func NewAccessTokenValidator(secret []byte, issuer string, clock Clock) (*AccessTokenValidator, error) {
	if len(secret) == 0 || issuer == "" {
		return nil, NewError(ErrorInvalid, "invalid access token settings")
	}
	if clock == nil {
		clock = RealClock{}
	}
	return &AccessTokenValidator{
		secret: append([]byte(nil), secret...),
		issuer: issuer,
		clock:  clock,
	}, nil
}

// Validate verifies the token format, algorithm, signature, issuer and
// expiration. Every failure is returned as the same safe unauthorized error;
// token material and claim contents are deliberately not included in it.
func (v *AccessTokenValidator) Validate(token string) (AccessTokenClaims, error) {
	if v == nil || len(v.secret) == 0 || v.issuer == "" || v.clock == nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}

	parts := splitAccessToken(token)
	if parts == nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	headerBytes, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	var header accessTokenHeader
	if err := decodeStrictJSON(headerBytes, &header); err != nil || header.Alg != "HS256" {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}

	suppliedSignature, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil || len(suppliedSignature) != sha256.Size {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	mac := hmac.New(sha256.New, v.secret)
	_, _ = mac.Write([]byte(parts[0] + "." + parts[1]))
	if subtle.ConstantTimeCompare(mac.Sum(nil), suppliedSignature) == 0 {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}

	claimsBytes, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	var claims AccessTokenClaims
	now := v.clock.Now().Unix()
	if err := decodeStrictJSON(claimsBytes, &claims); err != nil ||
		claims.Sub == "" || claims.Email == "" || claims.Iss != v.issuer || claims.JTI == "" ||
		claims.Exp <= claims.Iat || claims.Exp <= now || claims.Iat > now {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	if _, err := ValidateEmail(claims.Email); err != nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	return claims, nil
}

// ValidateAccessToken is the stateless convenience form of validation.
